ALTER TABLE "app"."run_events" DROP CONSTRAINT "run_events_type_catalog";--> statement-breakpoint
ALTER TABLE "app"."node_runs" ADD COLUMN "failure_ref" jsonb;--> statement-breakpoint
ALTER TABLE "app"."node_runs" ADD COLUMN "failure_handler_entry_key" varchar(256);--> statement-breakpoint
ALTER TABLE "app"."node_runs" ADD COLUMN "failure_handler_sink_key" varchar(256);--> statement-breakpoint
ALTER TABLE "app"."node_runs" ADD COLUMN "failure_handling" varchar(16);--> statement-breakpoint
ALTER TABLE "app"."workflow_runs" ADD COLUMN "handled_failure_count" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "app"."node_runs" ADD CONSTRAINT "node_runs_failure_handling_complete" CHECK ((((failure_ref IS NULL) AND (failure_handler_entry_key IS NULL) AND (failure_handler_sink_key IS NULL) AND (failure_handling IS NULL)) OR ((failure_ref IS NOT NULL) AND (failure_handler_entry_key IS NOT NULL) AND (failure_handler_sink_key IS NOT NULL) AND (failure_handling IN ('pending', 'handled')) AND (status = 'failed') AND (current_attempt_id IS NOT NULL) AND (current_attempt_number > 0))) IS TRUE);--> statement-breakpoint
ALTER TABLE "app"."node_runs" ADD CONSTRAINT "node_runs_failure_ref_bounded" CHECK (failure_ref IS NULL OR octet_length(failure_ref::text) <= 4096);--> statement-breakpoint
ALTER TABLE "app"."run_events" ADD CONSTRAINT "run_events_type_catalog" CHECK (((type)::text = ANY (ARRAY[('run.queued'::character varying)::text, ('run.started'::character varying)::text, ('run.waiting'::character varying)::text, ('run.cancel_requested'::character varying)::text, ('run.succeeded'::character varying)::text, ('run.failed'::character varying)::text, ('run.canceled'::character varying)::text, ('run.timed_out'::character varying)::text, ('run.outcome_unknown'::character varying)::text, ('node.ready'::character varying)::text, ('node.reused'::character varying)::text, ('node.failure_routed'::character varying)::text, ('node.failure_handled'::character varying)::text, ('node.started'::character varying)::text, ('node.progress'::character varying)::text, ('node.waiting'::character varying)::text, ('node.retry_scheduled'::character varying)::text, ('node.succeeded'::character varying)::text, ('node.failed'::character varying)::text, ('node.skipped'::character varying)::text, ('node.canceled'::character varying)::text, ('node.timed_out'::character varying)::text, ('node.outcome_unknown'::character varying)::text])));--> statement-breakpoint
ALTER TABLE "app"."workflow_runs" ADD CONSTRAINT "workflow_runs_handled_failure_count_valid" CHECK (handled_failure_count >= 0 AND handled_failure_count <= 200);--> statement-breakpoint
GRANT UPDATE (failure_ref, failure_handler_entry_key, failure_handler_sink_key, failure_handling) ON app.node_runs TO {{app_role}};
GRANT UPDATE (handled_failure_count) ON app.workflow_runs TO {{app_role}};
